type Cache struct {
    mu sync.Mutex
    m  map[string]*Entry
}

func (c *Cache) Find(key string) *Entry {
    c.mu.Lock()
    defer c.mu.Unlock()
    return c.findLocked(key)      // mu is held
}

func (c *Cache) findLocked(key string) *Entry { /* assumes mu held */ return c.m[key] }
